<?php
if(!isset($user)||!$user){http_response_code(404);exit;}
$year=(int)query_text('year',(string)date('Y'));if($year<2020||$year>2100)$year=(int)date('Y');
?>
<div class="page-heading"><p class="eyebrow">PLAN WITH CONFIDENCE</p><h1>Leave Balances</h1><p class="muted">Available = allowance − approved − pending.</p></div>
<form method="get" class="table-tools"><input type="hidden" name="view" value="balances"><label>Year<input type="number" name="year" min="2020" max="2100" value="<?= $year ?>" required></label><button class="button">View Year</button></form>
<section class="panel policy-note"><h2>Leave Policy</h2><p>Default yearly allowances: 15 Annual · 15 Sick · 7 Emergency days. Personal leave uses Annual credits. Fast Leave: 3 uses per year (0.5 day each).</p><p class="muted">Monday–Friday only; holidays count. No carry-over or monthly accrual. Admins can adjust allowances.</p><details><summary>Other Leave Types</summary><p>For maternity, paternity, solo-parent, and other special leave, contact your administrator.</p></details></section>
<?php foreach($admin?$employees:[$user] as $person):$balance=leave_balance($pdo,(int)$person['id'],$year); ?>
<section class="panel balance-panel"><h2><?= e($person['name']) ?> <small>· <?= $year ?></small></h2><div class="table-scroll" role="region" aria-label="<?= e($person['name']) ?> leave balances" tabindex="0"><table class="data-table"><thead><tr><th>Leave Type</th><th>Allowance</th><th>Approved</th><th>Pending</th><th>Available</th></tr></thead><tbody><?php foreach($balance as $type=>$b):?><tr><th scope="row"><?= e(leave_label($type).($type==='Fast'?' (uses)':' (days)')) ?></th><td><?= $b['allowance'] ?></td><td><?= $b['approved'] ?></td><td><?= $b['pending'] ?></td><td><strong class="<?= $b['available']<0?'balance-warning':'' ?>"><?= $b['available'] ?></strong></td></tr><?php endforeach ?></tbody></table></div>
<?php if($admin):?><details><summary>Adjust Allowance</summary><form method="post"><?= csrf() ?><input type="hidden" name="action" value="allowance"><input type="hidden" name="user_id" value="<?= (int)$person['id'] ?>"><input type="hidden" name="year" value="<?= $year ?>"><div class="allowance-grid"><?php foreach($balance as $type=>$b):if($type==='Fast')continue;?><label><?= e(leave_label($type)) ?> Days<input type="number" name="<?= strtolower($type) ?>" min="0" max="260" value="<?= $b['allowance'] ?>" required></label><?php endforeach ?></div><small class="field-hint">Cannot be below approved and pending days.</small><button class="button">Save Allowance</button></form></details><?php endif ?></section>
<?php endforeach ?>
